param(
  [string]$BackupRoot,
  [string]$ExpectedCurrentVersion='2026.10.26.3',
  [string]$ExpectedLegacyCommit='d159cba',
  [string]$InstallRoot=(Join-Path $env:LOCALAPPDATA 'GRMetro\Performance Center'),
  [switch]$ValidateOnly,[switch]$ConfirmRestore,[switch]$RecoverOnly
)
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot 'package-files.ps1')
. (Join-Path $PSScriptRoot 'process-control.ps1')
. (Join-Path $PSScriptRoot 'release-identity.ps1')

function Assert-GrMetroLegacyRecoveryRoot([string]$Root,[switch]$AllowTestRoot) {
  $resolved=[IO.Path]::GetFullPath($Root).TrimEnd('\')
  if($AllowTestRoot){if($env:GRMETRO_UPDATER_TEST_MODE-ne'true'){throw 'Disposable legacy recovery roots are disabled outside tests.'}}
  else{$expected=[IO.Path]::GetFullPath((Join-Path $env:LOCALAPPDATA 'GRMetro\Performance Center')).TrimEnd('\');if($resolved-ne$expected){throw 'Legacy recovery targets only the installed per-user GRMetro application.'}}
  if(-not(Test-Path -LiteralPath $resolved -PathType Container)){throw 'The installed GRMetro application is missing.'}
  $current=$resolved;while($current){if(Test-Path $current){if((Get-Item $current -Force).Attributes-band[IO.FileAttributes]::ReparsePoint){throw 'Legacy recovery path contains a reparse point.'}};$current=[IO.Path]::GetDirectoryName($current)};return $resolved
}

function Test-GrMetroLegacyManagedBackup {
  param([string]$Root,[string]$Backup,[string]$CurrentVersion,[string]$LegacyCommit,[switch]$AllowTestRoot)
  $install=Assert-GrMetroLegacyRecoveryRoot $Root -AllowTestRoot:$AllowTestRoot;$backupRoot=[IO.Path]::GetFullPath($Backup).TrimEnd('\')
  if(-not$AllowTestRoot){$allowed=[IO.Path]::GetFullPath((Join-Path $env:LOCALAPPDATA 'GRMetro\Legacy Upgrade Backups')).TrimEnd('\');if(-not$backupRoot.StartsWith($allowed+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Legacy recovery backup is outside the protected backup directory.'}}
  $current=$backupRoot;while($current){if(Test-Path $current){if((Get-Item $current -Force).Attributes-band[IO.FileAttributes]::ReparsePoint){throw 'Legacy recovery backup path contains a reparse point.'}};$current=[IO.Path]::GetDirectoryName($current)}
  $inventoryPath=Join-Path $backupRoot 'SHA256-INVENTORY.json';$applicationRoot=Join-Path $backupRoot 'application';if(-not(Test-Path $inventoryPath -PathType Leaf)-or-not(Test-Path $applicationRoot -PathType Container)){throw 'Legacy managed-file backup is incomplete.'}
  try{$inventory=Get-Content $inventoryPath -Raw|ConvertFrom-Json}catch{throw 'Legacy backup inventory is malformed.'};if([int]$inventory.schemaVersion-ne1-or[string]$inventory.applicationVersion-ne'1.0.0'-or[string]$inventory.commit-ne$LegacyCommit){throw 'Legacy backup identity does not match the approved baseline.'}
  $records=@($inventory.files);if(-not$records.Count){throw 'Legacy backup inventory is empty.'};$seen=@{};foreach($record in $records){$relative=[string]$record.path;Assert-GrMetroPackagePath $relative;if($seen.ContainsKey($relative)){throw "Duplicate legacy backup path: $relative"};$seen[$relative]=$true;$source=Get-GrMetroPackageDestination $applicationRoot $relative;if(-not(Test-Path $source -PathType Leaf)){throw "Legacy backup file missing: $relative"};$item=Get-Item $source -Force;if($item.Attributes-band[IO.FileAttributes]::ReparsePoint){throw "Legacy backup file is a reparse point: $relative"};if([long]$record.bytes-ne$item.Length-or[string]$record.sha256-notmatch'^[A-Fa-f0-9]{64}$'-or(Get-FileHash $source -Algorithm SHA256).Hash-ne([string]$record.sha256).ToUpperInvariant()){throw "Legacy backup checksum mismatch: $relative"}}
  $legacyManifestPath=Get-GrMetroPackageDestination $applicationRoot 'scripts/windows/package-manifest.json';$legacyIdentityPath=Get-GrMetroPackageDestination $applicationRoot 'scripts/windows/package-build.json';try{$legacyManifest=Get-Content $legacyManifestPath -Raw|ConvertFrom-Json;$legacyIdentity=Get-Content $legacyIdentityPath -Raw|ConvertFrom-Json}catch{throw 'Legacy backup package metadata is malformed.'}
  if([int]$legacyManifest.version-ne2-or[string]$legacyIdentity.applicationVersion-ne'1.0.0'-or[string]$legacyIdentity.commit-ne$LegacyCommit){throw 'Legacy backup package metadata is incompatible.'};$legacyFiles=@($legacyManifest.files);if((($legacyFiles|Sort-Object)-join'|')-ne(($records.path|Sort-Object)-join'|')){throw 'Legacy backup inventory does not match its installed manifest.'}
  $installed=Get-GrMetroInstalledReleaseMetadata $install;if([string]$installed.releaseVersion-ne$CurrentVersion){throw "Installed GRMetro version $($installed.releaseVersion) does not match the approved recovery source version."};$recovery=Get-GrMetroUpgradeRecoveryAction $install;if($recovery-ne'none'){throw "A pending application transaction requires $recovery. Run recovery-only handling before starting post-success restore."}
  $currentManifest=Get-Content (Join-Path $install 'scripts/windows/package-manifest.json')-Raw|ConvertFrom-Json;$currentFiles=@(Get-GrMetroManifestFiles $currentManifest);foreach($relative in $currentFiles){if(-not(Test-Path (Get-GrMetroPackageDestination $install $relative)-PathType Leaf)){throw "Current managed file missing: $relative"}}
  return [pscustomobject]@{InstallRoot=$install;BackupRoot=$backupRoot;ApplicationRoot=$applicationRoot;Inventory=$inventory;LegacyFiles=$legacyFiles;CurrentFiles=$currentFiles;CurrentIdentity=$installed;RecoveryAction=$recovery}
}

function Prepare-GrMetroLegacyManagedRecovery($Preflight) {
  $install=$Preflight.InstallRoot;$upgradeRoot=Get-GrMetroUpgradeRoot $install;if(Test-Path $upgradeRoot){throw 'A GRMetro application transaction already exists.'};$stage=Join-Path $upgradeRoot 'stage';$rollback=Join-Path $upgradeRoot 'backup';New-Item -ItemType Directory -Force -Path $stage,$rollback|Out-Null
  try{
    foreach($relative in $Preflight.LegacyFiles){$source=Get-GrMetroPackageDestination $Preflight.ApplicationRoot $relative;$destination=Get-GrMetroPackageDestination $stage $relative;New-Item -ItemType Directory -Force -Path ([IO.Path]::GetDirectoryName($destination))|Out-Null;Copy-Item $source $destination;if((Get-FileHash $source -Algorithm SHA256).Hash-ne(Get-FileHash $destination -Algorithm SHA256).Hash){throw "Legacy recovery stage verification failed: $relative"}}
    $affected=@($Preflight.CurrentFiles+$Preflight.LegacyFiles|Sort-Object -Unique);$records=@();foreach($relative in $affected){$destination=Get-GrMetroPackageDestination $install $relative;$existed=Test-Path $destination -PathType Leaf;$hash=$null;if($existed){$backup=Get-GrMetroPackageDestination $rollback $relative;New-Item -ItemType Directory -Force -Path ([IO.Path]::GetDirectoryName($backup))|Out-Null;Copy-Item $destination $backup;$hash=(Get-FileHash $destination -Algorithm SHA256).Hash;if((Get-FileHash $backup -Algorithm SHA256).Hash-ne$hash){throw "Current-version rollback backup verification failed: $relative"}};$records+=[ordered]@{path=$relative;existed=[bool]$existed;backupSha256=$hash}}
    Write-GrMetroUpgradeJournal (Join-Path $upgradeRoot 'journal.json') ([ordered]@{version=2;status='prepared';installRoot=$install;files=$records});[IO.File]::WriteAllText((Join-Path $upgradeRoot 'legacy-recovery.json'),((([ordered]@{schemaVersion=1;backupRoot=$Preflight.BackupRoot;legacyFiles=$Preflight.LegacyFiles}|ConvertTo-Json -Depth 4))+[Environment]::NewLine),(New-Object Text.UTF8Encoding($false)));return $upgradeRoot
  }catch{if(Test-Path $upgradeRoot){$journal=Join-Path $upgradeRoot 'journal.json';if(-not(Test-Path $journal)){Remove-GrMetroUpgradeRoot $install}};throw}
}

function Apply-GrMetroLegacyManagedRecovery($Preflight) {
  $install=$Preflight.InstallRoot;$upgradeRoot=Get-GrMetroUpgradeRoot $install;$journalPath=Join-Path $upgradeRoot 'journal.json';$stage=Join-Path $upgradeRoot 'stage';$journal=Get-Content $journalPath -Raw|ConvertFrom-Json;if([int]$journal.version-ne2-or[string]$journal.status-ne'prepared'){throw 'Legacy recovery transaction is not prepared.'};Assert-GrMetroUpgradeRollbackSources $install $journal
  try{$journal.status='applying';Write-GrMetroUpgradeJournal $journalPath $journal;foreach($relative in $Preflight.LegacyFiles){$source=Get-GrMetroPackageDestination $stage $relative;$destination=Get-GrMetroPackageDestination $install $relative;New-Item -ItemType Directory -Force -Path ([IO.Path]::GetDirectoryName($destination))|Out-Null;Copy-Item $source $destination -Force};$legacySet=@{};foreach($relative in $Preflight.LegacyFiles){$legacySet[$relative]=$true};$obsolete=@($Preflight.CurrentFiles|Where-Object{-not$legacySet.ContainsKey($_)});foreach($relative in $obsolete){$destination=Get-GrMetroPackageDestination $install $relative;if(Test-Path $destination -PathType Leaf){Remove-Item $destination -Force}};Remove-GrMetroEmptyApplicationDirectories $install $obsolete;$journal.status='applied';Write-GrMetroUpgradeJournal $journalPath $journal;foreach($record in @($Preflight.Inventory.files)){$path=Get-GrMetroPackageDestination $install ([string]$record.path);if((Get-FileHash $path -Algorithm SHA256).Hash-ne([string]$record.sha256).ToUpperInvariant()){throw "Restored legacy file verification failed: $($record.path)"}};return [pscustomobject]@{Status='applied';ObsoleteFiles=$obsolete}}
  catch{$failure=$_;try{$null=Restore-GrMetroUpgradeTransaction $install}catch{throw "Legacy recovery failed: $($failure.Exception.Message). Automatic rollback also failed: $($_.Exception.Message)"};throw $failure}
}

function Get-GrMetroNonManagedHashes([string]$Root,[string[]]$ManagedFiles) {$managed=@{};foreach($relative in $ManagedFiles){$managed[$relative.Replace('\','/')]=$true};$result=@{};foreach($file in @(Get-ChildItem $Root -Recurse -File -Force)){$relative=$file.FullName.Substring($Root.TrimEnd('\').Length+1).Replace('\','/');if(-not$managed.ContainsKey($relative)){$result[$relative]=(Get-FileHash $file.FullName -Algorithm SHA256).Hash}};return $result}

function Invoke-GrMetroPostSuccessRecovery {
  param([string]$Root,[string]$Backup,[string]$CurrentVersion,[string]$LegacyCommit,[switch]$ValidateOnly,[switch]$Confirm,[switch]$Recover,[switch]$AllowTestRoot,[scriptblock]$StopAction={param($install)Stop-GrMetroUpgradeProcesses $install},[scriptblock]$StartAction={param($install)Start-GrMetroInstalledApplication $install},[scriptblock]$RestartAction={param($install,$state)Restart-GrMetroAfterFailedUpgrade $install $state})
  $install=Assert-GrMetroLegacyRecoveryRoot $Root -AllowTestRoot:$AllowTestRoot
  if($Recover){$action=Get-GrMetroUpgradeRecoveryAction $install;if($action-eq'none'){return [pscustomobject]@{Status='no-pending-recovery'}};$prior=&$StopAction $install;try{$rolledBack=Restore-GrMetroUpgradeTransaction $install;&$RestartAction $install $prior;return [pscustomobject]@{Status=$(if($rolledBack){'recovered-current-version'}else{'completed-transaction-cleanup'});RolledBack=[bool]$rolledBack;RecoveryAction=$action}}catch{throw "Interrupted legacy recovery could not restore or clean the pending application transaction: $($_.Exception.Message)"}}
  $preflight=Test-GrMetroLegacyManagedBackup $install $Backup $CurrentVersion $LegacyCommit -AllowTestRoot:$AllowTestRoot;if($ValidateOnly){return [pscustomobject]@{Status='validated';CurrentVersion=$preflight.CurrentIdentity.releaseVersion;LegacyCommit=$LegacyCommit;ManagedFiles=$preflight.LegacyFiles.Count;RecoveryAction=$preflight.RecoveryAction}}
  if(-not$Confirm){throw 'Post-success recovery requires explicit restore confirmation.'};$null=Prepare-GrMetroLegacyManagedRecovery $preflight;$prior=$null;$stopped=$false;$commitCompleted=$false
  try{$prior=&$StopAction $install;$stopped=$true;$privateBefore=Get-GrMetroNonManagedHashes $install (@($preflight.CurrentFiles+$preflight.LegacyFiles|Sort-Object -Unique));$result=Apply-GrMetroLegacyManagedRecovery $preflight;$privateAfter=Get-GrMetroNonManagedHashes $install $preflight.LegacyFiles;if($privateBefore.Count-ne$privateAfter.Count){throw 'Private/nonmanifest file inventory changed during recovery.'};foreach($relative in $privateBefore.Keys){if($privateAfter[$relative]-ne$privateBefore[$relative]){throw "Private/nonmanifest file changed during recovery: $relative"}};$cleanupWarning=$null;try{Complete-GrMetroUpgradeTransaction $install;$commitCompleted=$true}catch{$journalPath=Join-Path (Get-GrMetroUpgradeRoot $install) 'journal.json';$status=$null;if(Test-Path $journalPath){try{$status=[string](Get-Content $journalPath -Raw|ConvertFrom-Json).status}catch{}};if($status-ne'completed'){throw};$commitCompleted=$true;$cleanupWarning=$_.Exception.Message};&$StartAction $install;return [pscustomobject]@{Status=$(if($cleanupWarning){'complete-cleanup-required'}else{'complete'});RestoredVersion='1.0.0';RestoredCommit=$LegacyCommit;ManagedFiles=$preflight.LegacyFiles.Count;PrivateFilesPreserved=$privateBefore.Count;UpdateHostPreserved=$true;CleanupWarning=$cleanupWarning}}
  catch{$failure=$_;$rollbackFailure=$null;if($commitCompleted){throw "Legacy managed application was restored, but final cleanup or restart failed: $($failure.Exception.Message)"};if(Test-Path (Get-GrMetroUpgradeRoot $install)){try{$null=Restore-GrMetroUpgradeTransaction $install}catch{$rollbackFailure=$_}};if($stopped-and-not$rollbackFailure){try{&$RestartAction $install $prior}catch{$rollbackFailure=$_}};if($rollbackFailure){throw "Post-success recovery failed: $($failure.Exception.Message). Current-version rollback also failed: $($rollbackFailure.Exception.Message)"};throw "$($failure.Exception.Message) The current application version was restored."}
}

if($MyInvocation.InvocationName-ne'.'){
  if($RecoverOnly){Invoke-GrMetroPostSuccessRecovery -Root $InstallRoot -Backup $BackupRoot -CurrentVersion $ExpectedCurrentVersion -LegacyCommit $ExpectedLegacyCommit -Recover;exit}
  if(-not$BackupRoot){throw 'BackupRoot is required.'};Invoke-GrMetroPostSuccessRecovery -Root $InstallRoot -Backup $BackupRoot -CurrentVersion $ExpectedCurrentVersion -LegacyCommit $ExpectedLegacyCommit -ValidateOnly:$ValidateOnly -Confirm:$ConfirmRestore
}
